final class WorldshaperRenderingTest {
    private static final BlockPos MATERIAL=new BlockPos(95008,6,24),TARGET=new BlockPos(95016,5,20),CHEST=new BlockPos(95025,5,20);
    private static final String STOCK="Original Worldshaper custody diamonds";
    static void run(ClientGameTestContext c,TestSingleplayerContext w){
        int width=c.computeOnClient(client->client.getWindow().getScreenWidth()),height=c.computeOnClient(client->client.getWindow().getScreenHeight()),scale=c.computeOnClient(client->client.options.guiScale().get());
        var camera=c.computeOnClient(client->client.options.getCameraType());boolean hidden=c.computeOnClient(client->client.gui.hud.isHidden());
        try{c.runOnClient(client->{client.getWindow().setWindowed(Math.max(width,960),Math.max(height,640));client.options.guiScale().set(2);client.resizeGui();client.options.setCameraType(CameraType.FIRST_PERSON);if(client.gui.hud.isHidden())client.gui.hud.toggle();});c.waitFor(client->client.getWindow().getGuiScaledWidth()>=480&&client.getWindow().getGuiScaledHeight()>=320&&client.getWindow().getGuiScale()==2,250);scene(c,w);}finally{c.getInput().releaseKey(InputConstants.KEY_LSHIFT);c.getInput().releaseKey(options->options.keyAttack);c.getInput().releaseKey(options->options.keyUse);c.runOnClient(client->{client.options.setCameraType(camera);client.options.guiScale().set(scale);client.getWindow().setWindowed(width,height);client.resizeGui();if(client.gui.hud.isHidden()!=hidden)client.gui.hud.toggle();});}
    }
    private static void scene(ClientGameTestContext c,TestSingleplayerContext w){
        var server=w.getServer();server.runCommand("gamemode spectator @p");server.runCommand("tp @p 95008.5 10 8.5");c.waitFor(client->client.level.isLoaded(MATERIAL)&&client.level.isLoaded(CHEST),450);NativeScreenshotReadiness.beforeFloor(c, w, new BlockPos(95000, 4, 0), new BlockPos(95040, 4, 32), MATERIAL.below(), TARGET, CHEST);
        server.runCommand("fill 95000 4 0 95040 4 32 minecraft:smooth_quartz");
        NativeScreenshotReadiness.afterFloor(c, w, new BlockPos(95000, 4, 0), new BlockPos(95040, 4, 32));server.runCommand("clear @p");
        stand(c,w,95008.5,8.5);select(c,w,InputConstants.KEY_2,1);select(c,w,InputConstants.KEY_1,0);
        server.runOnServer(ignored->{var level=w.getConnection().getServerLevel();var player=actual(level);var tool=new ItemStack(AllItems.WORLDSHAPER);tool.set(DataComponents.CUSTOM_NAME,Component.literal("Original native Worldshaper"));player.getInventory().setItem(0,tool);player.getInventory().setItem(9,diamonds());level.setBlockAndUpdate(MATERIAL,Blocks.POLISHED_ANDESITE.defaultBlockState());level.setBlockAndUpdate(TARGET,Blocks.STONE.defaultBlockState());level.setBlockAndUpdate(CHEST,Blocks.CHEST.defaultBlockState());((ChestBlockEntity)level.getBlockEntity(CHEST)).setItem(0,diamonds());});
        c.waitFor(client->client.player.getMainHandItem().is(AllItems.WORLDSHAPER)&&client.player.getInventory().getItem(9).getCount()==7,250);
        look(c,Vec3.atCenterOf(MATERIAL));c.waitFor(client->client.hitResult==null||client.hitResult.getType()!=HitResult.Type.BLOCK,250);
        c.getInput().pressKey(options->options.keyAttack);await(c,w,level->actual(level).getMainHandItem().get(AllDataComponents.SHAPER_BLOCK_USED)==Blocks.POLISHED_ANDESITE.defaultBlockState(),250,"Physical left click did not select the actual long-range source block via the server ray");
        c.waitFor(client->client.player.getMainHandItem().get(AllDataComponents.SHAPER_BLOCK_USED)==Blocks.POLISHED_ANDESITE.defaultBlockState(),250);verifyItem(c);fullyEquipped(c);shot(c,"create-vulkan-worldshaper-real-long-range-left-click-source-material-and-four-native-parts",false,true);
        open(c);shot(c,"create-vulkan-worldshaper-physical-shift-use-original-gui-native-block-pip-and-item-glow",false,true);
        var widthInput=c.computeOnClient(client->((WorldshaperScreen)client.gui.screen()).children().stream().filter(ScrollInput.class::isInstance).map(ScrollInput.class::cast).filter(widget->widget.getWidth()==18&&widget.getX()==originX(client)+56).findFirst().orElseThrow());
        move(c,c.computeOnClient(client->physical(client,widthInput.getX()+9,widthInput.getY()+9)));c.getInput().scroll(1);c.waitTicks(2);c.getInput().scroll(1);c.waitTicks(2);
        c.runOnClient(client->{if(widthInput.getState()!=3)throw new AssertionError("Two actual source width wheel events did not produce3");});click(c,34,88); // Original Place tool button, not a direct component assignment.
        shot(c,"create-vulkan-worldshaper-real-width-wheel-and-source-place-button",false,true);click(c,210,88);c.waitFor(client->client.gui.screen()==null,250);
        await(c,w,level->{var stack=actual(level).getMainHandItem();return stack.get(AllDataComponents.SHAPER_TOOL)==TerrainTools.Place&&new BlockPos(3,1,1).equals(stack.get(AllDataComponents.SHAPER_BRUSH_PARAMS));},250,"Actual source GUI close packet did not publish the physically selected native brush settings");
        stand(c,w,95016.5,12.5);look(c,Vec3.atCenterOf(TARGET));c.waitFor(client->ZapperClient.latest!=null&&ZapperClient.latest.blocks()==3&&ZapperClient.latest.faces().size()==14&&ZapperClient.latest.edges().size()==20,250);fullyEquipped(c);shot(c,"create-vulkan-worldshaper-source-three-cell-native-checker-faces-and-cluster-boundary",true,true);
        c.runOnClient(client->WorldshaperNativeProbe.begin("create-vulkan-worldshaper-physical-use-real-edit-and-original-beam"));try{c.getInput().pressKey(options->options.keyUse);await(c,w,level->List.of(TARGET.west(),TARGET,TARGET.east()).stream().allMatch(pos->LoadedLevelAccess.blockState(level,pos).is(Blocks.POLISHED_ANDESITE)),220,"Actual source use did not edit the three original native cells");c.takeScreenshot("create-vulkan-worldshaper-physical-use-real-edit-and-original-beam");}finally{c.runOnClient(client->WorldshaperNativeProbe.end(true,true,true));}
        assertCustody(c,w);var oldModel=c.computeOnClient(client->WorldshaperItemRenderer.INSTANCE.extractArgument(client.player.getMainHandItem()).draws.getFirst().quads());var reload=c.computeOnClient(Minecraft::reloadResourcePacks);c.waitFor(client->reload.isDone()&&client.gui.overlay()==null,650);reload.join();c.runOnClient(client->{if(WorldshaperItemRenderer.INSTANCE.extractArgument(client.player.getMainHandItem()).draws.getFirst().quads()==oldModel)throw new AssertionError("Native resource reload retained old Worldshaper model");});verifyItem(c);fullyEquipped(c);shot(c,"create-vulkan-worldshaper-native-reload-refreshes-source-mesh-and-preserves-real-settings",true,true);
        var previous=server.computeOnServer(ignored->(ChestBlockEntity)w.getConnection().getServerLevel().getBlockEntity(CHEST));server.runCommand("save-all flush");server.runCommand("gamemode spectator @p");server.runCommand("tp @p 96400.5 15 8.5");await(c,w,level->level.getChunkSource().getChunkNow(CHEST.getX()>>4,CHEST.getZ()>>4)==null,850,"Actual Worldshaper source scene did not leave FULL status");NativeFixtureChunkUnload.finish(c,w,previous);
        server.runCommand("tp @p 95016.5 10 12.5");await(c,w,level->LoadedLevelAccess.blockEntity(level,CHEST) instanceof ChestBlockEntity chest&&chest!=previous&&ItemStack.matches(chest.getItem(0),diamonds()),650,"Fresh native chunk failed to restore the exact original Worldshaper custody owner/stock");stand(c,w,95016.5,12.5);assertCustody(c,w);look(c,Vec3.atCenterOf(TARGET));c.waitFor(client->ZapperClient.latest!=null&&ZapperClient.latest.blocks()==3,250);shot(c,"create-vulkan-worldshaper-fresh-native-owner-original-settings-and-source-edits-after-save-unload",true,true);
        c.runOnClient(client->client.options.setCameraType(CameraType.THIRD_PERSON_FRONT));c.waitTicks(4);c.runOnClient(client->{var renderer=(net.minecraft.client.renderer.entity.player.AvatarRenderer<net.minecraft.client.player.LocalPlayer>)(Object)client.getEntityRenderDispatcher().getRenderer(client.player);var state=renderer.createRenderState();renderer.extractRenderState(client.player,state,.5f);if(state.getArmPose(client.player.getMainArm())!=net.minecraft.client.model.HumanoidModel.ArmPose.CROSSBOW_HOLD||state.getMainHandItemState().isEmpty())throw new AssertionError("Real native Worldshaper third-person source arm pose/item missing");});shot(c,"create-vulkan-worldshaper-native-third-person-source-crossbow-hold-and-original-tool",true,true);server.runCommand("gamemode spectator @p");
    }
    private static void assertCustody(ClientGameTestContext c,TestSingleplayerContext w){w.getServer().runOnServer(ignored->{var level=w.getConnection().getServerLevel();var player=actual(level);var stack=player.getMainHandItem();if(player.hasInfiniteMaterials()||!stack.is(AllItems.WORLDSHAPER)||stack.getCount()!=1||stack.getDamageValue()!=0||stack.get(AllDataComponents.SHAPER_TOOL)!=TerrainTools.Place||!new BlockPos(3,1,1).equals(stack.get(AllDataComponents.SHAPER_BRUSH_PARAMS))||stack.get(AllDataComponents.SHAPER_BLOCK_USED)!=Blocks.POLISHED_ANDESITE.defaultBlockState()||!ItemStack.matches(player.getInventory().getItem(9),diamonds())||!(LoadedLevelAccess.blockEntity(level,CHEST) instanceof ChestBlockEntity chest)||!ItemStack.matches(chest.getItem(0),diamonds()))throw new AssertionError("Actual native source Worldshaper changed original tool/settings/stock/owner or fabricated creative abilities");});}
    private static void verifyItem(ClientGameTestContext c){c.runOnClient(client->{var source=WorldshaperItemRenderer.INSTANCE.extractArgument(client.player.getMainHandItem());if(!(source instanceof ZapperItemRenderer.ZapperState zapper)||source.draws.size()!=4||zapper.emission.size()!=2||source.draws.stream().anyMatch(draw->draw.quads().isEmpty()||!draw.transform().isFinite())||source.extents.length!=8)throw new AssertionError("Real native Worldshaper source parts/emissive meshes/bounds incomplete");var pair=WorldshaperRenderHandler.extract(List.of(BlockPos.ZERO,BlockPos.ZERO.east()),List.of());if(pair.blocks()!=2||pair.faces().size()!=10||pair.edges().size()!=16)throw new AssertionError("Native cluster retains internal coplanar seams; actual blocks="+pair.blocks()+", faces="+pair.faces().size()+", edges="+pair.edges().size()+", nativeFaces="+pair.faces()+", nativeEdges="+pair.edges());});}
    private static void fullyEquipped(ClientGameTestContext c){c.waitFor(client->{var state=new FirstPersonHandsAndItemsRenderState();client.player.firstPersonHandsAndItems().extractRenderState(client.player,1,state);return state.mainHandItem.is(AllItems.WORLDSHAPER)&&state.oldMainHandHeight>.999&&state.mainHandHeight>.999&&((EquipmentHandsAccess)state).create$equipmentHands().main.custom;},250);}
    private static void open(ClientGameTestContext c){c.getInput().holdKey(InputConstants.KEY_LSHIFT);try{c.waitFor(client->client.player.isShiftKeyDown(),200);c.waitTicks(2);c.getInput().pressKey(options->options.keyUse);c.waitFor(client->client.gui.screen() instanceof WorldshaperScreen,250);}finally{c.getInput().releaseKey(InputConstants.KEY_LSHIFT);}c.waitTicks(3);}
    private static void stand(ClientGameTestContext c,TestSingleplayerContext w,double x,double z){w.getServer().runCommand("gamemode survival @p");w.getServer().runCommand("tp @p "+x+" 5 "+z);c.waitFor(client->!client.player.isSpectator()&&client.player.onGround()&&Math.abs(client.player.getX()-x)<.1&&Math.abs(client.player.getZ()-z)<.1,250);}
    private static void select(ClientGameTestContext c,TestSingleplayerContext w,int key,int slot){c.getInput().pressKey(key);c.waitFor(client->client.player.getInventory().getSelectedSlot()==slot,200);await(c,w,level->actual(level).getInventory().getSelectedSlot()==slot,200,"Actual source selected slot was not acknowledged");}
    private static void look(ClientGameTestContext c,Vec3 target){var angle=c.computeOnClient(client->{var delta=target.subtract(client.player.getEyePosition());return new Vec2((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)),(float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z))));});c.getInput().lookAt(angle.x,angle.y);c.waitTicks(2);}
    private static int originX(Minecraft client){return(client.gui.screen().width-234)/2-10;}
    private static void click(ClientGameTestContext c,int x,int y){var point=c.computeOnClient(client->physical(client,originX(client)+x,(client.gui.screen().height-103)/2f+y));move(c,point);c.getInput().pressMouse(InputConstants.MOUSE_BUTTON_LEFT);c.waitTicks(2);}
    private static void move(ClientGameTestContext c,Vec2 point){c.getInput().setCursorPos(point.x,point.y);c.waitTicks(2);}
    private static Vec2 physical(Minecraft client,float x,float y){var window=client.getWindow();return new Vec2(x*window.getScreenWidth()/window.getGuiScaledWidth(),y*window.getScreenHeight()/window.getGuiScaledHeight());}
    private static ItemStack diamonds(){var stack=new ItemStack(Items.DIAMOND,7);stack.set(DataComponents.CUSTOM_NAME,Component.literal(STOCK));return stack;}
    private static ServerPlayer actual(ServerLevel level){return level.getServer().getPlayerList().getPlayers().getFirst();}
    private static void await(ClientGameTestContext c,TestSingleplayerContext w,Predicate<ServerLevel> predicate,int ticks,String failure){var result=new AtomicBoolean();for(int tick=0;tick<ticks&&!result.get();tick++){w.getServer().runOnServer(ignored->result.set(predicate.test(w.getConnection().getServerLevel())));if(!result.get())c.waitTicks(1);}if(!result.get())throw new AssertionError(failure);}
    private static void shot(ClientGameTestContext c,String name,boolean preview,boolean item){c.runOnClient(client->WorldshaperNativeProbe.begin(name));try{c.takeScreenshot(name);}finally{c.runOnClient(client->WorldshaperNativeProbe.end(preview,item,false));}}
    private WorldshaperRenderingTest(){}
}
